1	<!doctype html>
2	<html lang="pt-BR">
3	<head>
4	<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
5	<title>AutoSeguro · Nova cotação</title>
6	<style>
7	/* Mock da tela Conversas v2 — cotação guiada. Paleta e casca herdadas de docs/design/ui.css. */
8	:root{
9	  --fundo:#16012F; --superficie:#1F0A40; --superficie-2:#2A1152; --borda:#3B2068;
10	  --texto:#F2ECFF; --texto-fraco:#B9A8D9; --texto-mais-fraco:#8B79B0;
11	  --magenta:#FF00FF; --ciano:#00FFFF; --azul:#198BF5;
12	  --ok:#3DDC97; --alerta:#FFC857; --falha:#FF5C7A;
13	  --r:14px; --mono:ui-monospace,"Cascadia Mono",Consolas,monospace;
14	  --lateral:248px;
15	}
16	*{box-sizing:border-box}
17	[hidden]{display:none!important}
18	html,body{height:100%}
19	body{margin:0;background:var(--fundo);color:var(--texto);
20	     font:15px/1.5 system-ui,"Segoe UI",Roboto,sans-serif;
21	     background-image:radial-gradient(900px 500px at 15% -10%, rgba(255,0,255,.10), transparent 60%),
22	                      radial-gradient(800px 500px at 92% 0%, rgba(0,255,255,.07), transparent 55%);
23	     background-attachment:fixed}
24	a{color:var(--ciano)}
25	button{font:inherit;color:inherit}
26	:focus-visible{outline:2px solid var(--ciano);outline-offset:2px}
27	
28	/* ───── casca (igual ao mock atual) ───── */
29	.app{display:grid;grid-template-columns:var(--lateral) 1fr;height:100vh}
30	@media (max-width:860px){ .app{grid-template-columns:1fr} .lateral{display:none} }
31	.lateral{background:rgba(22,1,47,.72);border-right:1px solid var(--borda);padding:18px 14px;
32	         display:flex;flex-direction:column;gap:18px;backdrop-filter:blur(6px)}
33	.produto{display:flex;flex-direction:column;gap:3px;padding:4px 8px 0}
34	.produto b{font-size:19px;position:relative;display:inline-block;isolation:isolate}
35	.produto b::before,.produto b::after{content:attr(data-t);position:absolute;inset:0;z-index:-1}
36	.produto b::before{color:var(--magenta);transform:translate(-2px,1px)}
37	.produto b::after{color:var(--ciano);transform:translate(2px,-1px)}
38	.produto span{color:var(--texto-mais-fraco);font-size:11.5px}
39	.menu{display:flex;flex-direction:column;gap:3px}
40	.menu .grupo{color:var(--texto-mais-fraco);font-size:10.5px;text-transform:uppercase;letter-spacing:.12em;padding:12px 10px 5px}
41	.menu a{display:flex;align-items:center;gap:10px;padding:9px 11px;border-radius:10px;color:var(--texto-fraco);
42	        text-decoration:none;font-size:14px;border:1px solid transparent}
43	.menu a:hover{background:var(--superficie);color:var(--texto)}
44	.menu a[aria-current="page"]{background:var(--superficie-2);color:var(--texto);border-color:var(--borda);box-shadow:inset 2px 0 0 var(--magenta)}
45	.menu a .ic{width:18px;text-align:center}
46	.selo{margin-top:auto;background:rgba(255,255,255,.04);border:1px solid var(--borda);border-radius:12px;padding:9px 10px}
47	.selo small{color:var(--texto-mais-fraco);font-size:10.5px;line-height:1.3;display:block}
48	
49	/* ───── área principal ───── */
50	.principal{display:flex;flex-direction:column;min-width:0;height:100vh}
51	.barra{display:flex;align-items:center;gap:10px;padding:10px 20px;border-bottom:1px solid var(--borda);flex-wrap:wrap}
52	.barra h1{font-size:15px;margin:0;font-weight:600}
53	.selo-mock{font-family:var(--mono);font-size:10.5px;color:var(--alerta);border:1px dashed rgba(255,200,87,.5);
54	           border-radius:999px;padding:1px 9px}
55	.barra .dir{margin-left:auto;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
56	.barra label{font-size:12px;color:var(--texto-mais-fraco)}
57	.barra select,.btn-leve{background:var(--superficie);border:1px solid var(--borda);border-radius:9px;
58	           padding:5px 9px;font-size:12.5px;color:var(--texto);cursor:pointer}
59	.btn-leve:hover{border-color:var(--texto-mais-fraco)}
60	
61	.palco{flex:1;overflow-y:auto} /* sem scroll-behavior:smooth: com ele cada mensagem nova cancela a rolagem anterior (medido no teste) */
62	.coluna{max-width:760px;margin:0 auto;padding:28px 20px 24px}
63	
64	/* ───── hero (estado inicial) ───── */
65	.hero{min-height:calc(100vh - 190px);display:flex;flex-direction:column;align-items:center;justify-content:center;
66	      text-align:center;gap:14px;padding:20px 0}
67	.hero .marca{font-family:var(--mono);font-size:11.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--texto-mais-fraco)}
68	.hero h2{font-size:clamp(28px,4.2vw,42px);line-height:1.12;margin:0;max-width:17ch;text-wrap:balance;letter-spacing:-.8px}
69	.hero h2 em{font-style:normal;background:linear-gradient(90deg,var(--magenta),var(--ciano));
70	            -webkit-background-clip:text;background-clip:text;color:transparent}
71	.hero p{margin:0;color:var(--texto-fraco);max-width:52ch;font-size:16px}
72	.cta{margin-top:10px;border:0;border-radius:14px;padding:15px 26px;font-size:16.5px;font-weight:650;cursor:pointer;
73	     color:#16012F;background:linear-gradient(90deg,#FF5CFF,#7DFFFF);
74	     box-shadow:0 10px 34px -10px rgba(255,0,255,.55);transition:transform .15s,box-shadow .15s}
75	.cta:hover{transform:translateY(-1px);box-shadow:0 14px 40px -10px rgba(0,255,255,.5)}
76	.cta small{display:block;font-size:12px;font-weight:500;opacity:.75}
77	.garantias{list-style:none;padding:0;margin:18px 0 0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;width:100%}
78	@media (max-width:640px){ .garantias{grid-template-columns:1fr} }
79	.garantias li{background:rgba(31,10,64,.7);border:1px solid var(--borda);border-radius:12px;padding:11px 12px;
80	              text-align:left;font-size:12.5px;color:var(--texto-fraco)}
81	.garantias b{display:block;color:var(--texto);font-size:13px;margin-bottom:2px}
82	
83	/* ───── conversa ───── */
84	.fio{display:flex;flex-direction:column;gap:14px}
85	.msg{display:flex;gap:10px;align-items:flex-end;max-width:100%;animation:entra .22s ease-out}
86	@keyframes entra{from{opacity:.001;transform:translateY(6px)}to{opacity:1;transform:none}}
87	.avatar{width:28px;height:28px;border-radius:50%;flex:none;display:grid;place-items:center;font-size:12px;font-weight:700;
88	        color:#16012F;background:linear-gradient(135deg,var(--magenta),var(--ciano))}
89	.bolha{background:var(--superficie);border:1px solid var(--borda);border-radius:16px 16px 16px 4px;padding:10px 14px;max-width:560px}
90	.bolha .quem{display:block;font-family:var(--mono);font-size:10.5px;color:var(--texto-mais-fraco);margin-bottom:3px}
91	.bolha details summary{color:var(--ciano);cursor:pointer}
92	.msg.lead{justify-content:flex-end}
93	.msg.lead .bolha{background:rgba(255,0,255,.14);border-color:rgba(255,0,255,.35);border-radius:16px 16px 4px 16px}
94	.msg.sistema .bolha{background:transparent;border-style:dashed;color:var(--texto-fraco);font-size:13.5px}
95	.digitando{display:inline-flex;gap:4px;padding:4px 0}
96	.digitando i{width:6px;height:6px;border-radius:50%;background:var(--texto-mais-fraco);animation:pisca 1s infinite}
97	.digitando i:nth-child(2){animation-delay:.15s}.digitando i:nth-child(3){animation-delay:.3s}
98	@keyframes pisca{0%,100%{opacity:.25}50%{opacity:1}}
99	
100	/* progresso */
101	.progresso{display:flex;align-items:center;gap:10px;font-size:12px;color:var(--texto-mais-fraco);margin:0 0 18px}
102	.progresso .trilho{flex:1;height:4px;background:var(--superficie-2);border-radius:99px;overflow:hidden}
103	.progresso .trilho span{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--magenta),var(--ciano));transition:width .3s}
104	
105	/* cards de plano */
106	.planos{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:4px 0 0 38px}
107	@media (max-width:640px){ .planos{grid-template-columns:1fr;margin-left:0} }
108	.plano{background:var(--superficie);border:1px solid var(--borda);border-radius:14px;padding:14px;text-align:left;cursor:pointer;
109	       display:flex;flex-direction:column;gap:8px;transition:border-color .15s,transform .15s}
110	.plano:hover{border-color:var(--texto-mais-fraco);transform:translateY(-1px)}
111	.plano[aria-pressed="true"]{border-color:var(--ciano);box-shadow:0 0 0 1px var(--ciano) inset}
112	.plano h4{margin:0;font-size:16px}
113	.plano .franquia{font-size:12px;color:var(--texto-fraco)}
114	.plano .franquia b{font-variant-numeric:tabular-nums;color:var(--texto)}
115	.plano ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:3px;font-size:12.5px;color:var(--texto-fraco)}
116	.plano li::before{content:"✓ ";color:var(--ok)}
117	.plano li.extra{color:var(--texto)}
118	.plano .sub{font-size:11px;color:var(--texto-mais-fraco)}
119	
120	/* resumo e resultado */
121	.cartao{background:var(--superficie);border:1px solid var(--borda);border-radius:14px;padding:14px 16px;margin-left:38px;max-width:560px}
122	@media (max-width:640px){ .cartao{margin-left:0} }
123	.cartao dl{display:grid;grid-template-columns:auto 1fr auto;gap:6px 14px;margin:0;font-size:14px}
124	.cartao dt{color:var(--texto-mais-fraco)} .cartao dd{margin:0;font-variant-numeric:tabular-nums}
125	.cartao .alt{font-size:12px;background:none;border:0;color:var(--ciano);cursor:pointer;padding:0}
126	.preco{font-size:34px;font-weight:700;letter-spacing:-.5px;font-variant-numeric:tabular-nums;margin:2px 0}
127	.preco small{font-size:14px;font-weight:500;color:var(--texto-fraco)}
128	.chips{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}
129	.chip{border-radius:999px;padding:2px 9px;font-size:11.5px;border:1px solid var(--borda);color:var(--texto-fraco)}
130	.nota{font-size:12.5px;color:var(--texto-fraco);margin:6px 0 0}
131	.rastro{margin-top:10px;padding-top:8px;border-top:1px solid var(--borda);font-family:var(--mono);font-size:11px;color:var(--texto-mais-fraco)}
132	.rastro .ok{color:var(--ok)} .rastro .falha{color:var(--falha)}
133	.tag-exemplo{font-family:var(--mono);font-size:10px;color:var(--alerta)}
134	
135	/* ───── doca de resposta ───── */
136	.doca{border-top:1px solid var(--borda);background:rgba(22,1,47,.85);backdrop-filter:blur(6px)}
137	.doca .coluna{padding:12px 20px 16px}
138	.rapidas{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px}
139	.rapida{background:var(--superficie);border:1px solid var(--borda);border-radius:999px;padding:7px 14px;cursor:pointer;font-size:13.5px}
140	.rapida:hover{border-color:var(--ciano)}
141	.rapida.primaria{border-color:rgba(0,255,255,.55);color:var(--ciano)}
142	.caixa{display:flex;gap:8px;background:var(--superficie);border:1px solid var(--borda);border-radius:14px;padding:6px 6px 6px 14px;align-items:center}
143	.caixa:focus-within{border-color:var(--texto-mais-fraco)}
144	.caixa input{flex:1;background:none;border:0;color:var(--texto);font-size:15px;padding:8px 0;min-width:0;outline:none}
145	.caixa input::placeholder{color:var(--texto-mais-fraco)}
146	.caixa select#pais{background:var(--superficie-2);border:1px solid var(--borda);border-radius:9px;color:var(--texto);
147	           font:inherit;font-size:13px;padding:7px 6px;max-width:180px;flex:none}
148	.enviar{border:0;border-radius:10px;padding:9px 14px;font-weight:650;cursor:pointer;color:#16012F;background:var(--ciano)}
149	.enviar:disabled{opacity:.35;cursor:not-allowed}
150	.ajuda{font-size:11.5px;color:var(--texto-mais-fraco);margin:7px 2px 0;min-height:1em}
151	.ajuda.erro{color:var(--falha)}
152	
153	/* ───── especificação (gaveta) ───── */
154	.gaveta{position:fixed;inset:0 0 0 auto;width:min(460px,100%);background:var(--superficie);border-left:1px solid var(--borda);
155	        padding:22px 22px 40px;overflow-y:auto;transform:translateX(100%);transition:transform .25s;z-index:10}
156	.gaveta.aberta{transform:none}
157	.gaveta h3{margin:0 0 4px;font-size:18px}
158	.gaveta h4{margin:18px 0 6px;font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:var(--texto-mais-fraco)}
159	.gaveta ol,.gaveta ul{margin:0;padding-left:18px;font-size:13.5px;color:var(--texto-fraco);display:flex;flex-direction:column;gap:6px}
160	.gaveta b{color:var(--texto)}
161	.gaveta .fechar{float:right}
162	@media (prefers-reduced-motion:reduce){ *{animation:none!important;transition:none!important;scroll-behavior:auto!important} }
163	</style>
164	</head>
